"""B2 · episódios 32–38 — peças, musicais, poemas, contos e ensaios; um recorte, uma obra e uma cena por episódio."""
from v3.b2lib import *

EPS = []


def ep(s):
    V = s.pop('V')
    s['hot'] = [(x[0], x[1], x[2], x[4], x[5]) for x in V[:5]]
    s['vocab'] = [(x[0], x[1], x[2], x[3]) for x in V]
    for k, g in zip(('gap', 'gap2', 'gap3', 'gap4'), s.pop('gaps')):
        s[k] = g
    s['trap'], s['trap2'] = s.pop('traps')
    s['q1'], s['q2'], s['q3'] = s.pop('qs')
    s['pairs'] = [(x[0], x[4], x[1] + ' × ' + x[5]) for x in s['lab']]
    s['speak'] = s.pop('speak')
    add(s, EPS)


